parameters.new_string:
	var wg sync.WaitGroup
	var resultsWg sync.WaitGroup // New WaitGroup for results consumer

	// Start workers
	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for job := range jobs {
				// Simulate some work
				time.Sleep(time.Millisecond)

				// Fix 1: Race Condition with atomic counter
				processedCount.Add(1)

				results <- Result{JobID: job.ID, Val: job.ID * 2}
			}
		}(i)
	}

	// Start a goroutine to consume results concurrently
	resultsWg.Add(1)
	go func() {
		defer resultsWg.Done()
		for range results {
			// Just drain results, nothing else to do
		}
	}()

	// Send jobs
	go func() {
		for i := 0; i < numJobs; i++ {
			jobs <- Job{ID: i}
		}
		close(jobs)
	}()

	// Wait for all workers to finish processing jobs
	wg.Wait()

	// Close results channel AFTER all workers are done sending results
	close(results)

	// Wait for results consumer to finish draining the channel
	resultsWg.Wait()

	return int(processedCount.Load()), nil // Use Load() to get final value
}
